-- 扩充内置赛事目录，并给三级菜单与赛季自动解析提供稳定元数据。

ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    country_code = EXCLUDED.country_code,
    timezone = EXCLUDED.timezone,
    competition_kind = EXCLUDED.competition_kind,
    is_active = true,
    metadata = football.competitions.metadata || EXCLUDED.metadata,
    updated_at = now();

-- 旧内置目录补齐三级菜单和赛季模式，保留原有ID及所有引用。
UPDATE football.competitions
SET metadata = metadata || jsonb_build_object(
        'scope', CASE
            WHEN code IN ('UEFA-NATIONS-LEAGUE','UEFA-EURO','UEFA-EURO-QUAL','UEFA-WCQ') THEN 'national'
            WHEN code = 'GENERIC-FRIENDLY' THEN 'other'
            ELSE 'club'
        END,
        'menu_region', COALESCE(NULLIF(metadata->>'menu_region',''), NULLIF(metadata->>'region',''), country_code, '其他'),
        'confederation', COALESCE(NULLIF(metadata->>'confederation',''), CASE
            WHEN country_code IN ('UEFA','GB','ES','DE','IT','FR','NL','PT','BE','TR','CH','NO','FI','SE','DK','AT','GR','CZ','PL','IS') THEN 'UEFA'
            WHEN country_code IN ('AFC','KR','JP','CN','SA','AU','QA','AE') THEN 'AFC'
            WHEN country_code IN ('CONMEBOL','BR','AR','CO','CL','UY') THEN 'CONMEBOL'
            WHEN country_code IN ('CONCACAF','US','MX','CA') THEN 'CONCACAF'
            WHEN country_code IN ('CAF','EG','MA','ZA') THEN 'CAF'
            ELSE 'FIFA' END),
        'season_pattern', COALESCE(NULLIF(metadata->>'season_pattern',''), CASE
            WHEN country_code IN ('KR','JP','FI','NO','SE','IS','US','BR','AR','CO','CL','UY','CN') THEN 'calendar'
            WHEN code LIKE 'GENERIC-%' THEN 'calendar'
            ELSE 'cross_year' END)
    ),
    updated_at = now()
WHERE COALESCE((metadata->>'built_in')::boolean, false);
